insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p175', 'allemand', '3AS', 17, 175, '3AS p175 — Anhang : Bildquellen- und Textquellennachweis', E'Bildquellennachweis\nDie Fotos und Bilder sind u.a. den Zeitschriften «Jugendscala», «Juma» «Deutschland» und aus «Encarta Enzyklopedie 2006» entnommen.\n- Fotos aus «Jugendscala» April Mai 85.\n- Fotos aus der Zeitschrift «Juma» April 91- April 2002 - März 2003.\n- Bilder «Deutschland» Februar/März 2000.\n- Bilder «Encarta» Umweltverschmutzung in Deutschland.\n- Fotos und Bilder aus «www.Google.fr»\n- Bilder über Algerien aus «http : visalgérie - site voilà- fr 150758547.\n- Bilder aus «Tatsachen über Deutschland 1998»\nTextquellennachweis\n- Die Texte «Algerien», «Ben Badi» aus «Encarta Enzyklopedie 2006» Übersetzung von Herrn Elahcene\n- «der technische Fortschritt», «die Umwelt», «die neue Medien», «die Kommunikationsmittel», «Jugend und Droge», «die Arbeitswelt» sind von der Kommission bearbeitet. (Informationen aus Googel.fr)\n- Die deutsche Wirtschaft (Tatsachen über Deutschland 2005)\n- Österreich … aus «Encarta 2006» verarbeitet\n- Die Schweiz … aus «Encarta 2006» verarbeitet\n- Dialog seite 27 verarbeitet (Lernziel 1)\n- Computer, eine technische Revolution verarbeitet (Lernziel 2)\n- Wie werden die Menschen im Jahr 3000 leben ? verarbeitet (Lernziel 2)\n- Pillen statt Mahlzeiten, Deutschland Aktuell, Chassard et Weil LV1\n- Gutenberg, Auch-Wind, Edition Didier LV1\n- Begräbt uns der Müll Sprachillustrierte – Langenscheidts, Januar/März 1986 (verarbeitet)\n- Die Massenmedien (Tatsachen über Deutschland 2005)\n- Meinungen Lektion 5 (Ping pong)\n- Boah ey ! sowie so (5.2.2007)\n- Apropos Fortschritt, Auch-Wind, Edition Didier (verarbeitet)\n- Erst eine SMS, dann Zähneputzen (Ping pong)\n- Schriftzug «Post», Internet, w.w.w. google ;\n- Statistik aus (Themen 3)\n- Wie man ein Paket verschickt ? Sprechsituationen aus dem Alltag 2 (Inter Nationes)\n- Auf dem Postamt, Sprechsituationen aus dem Alltag 2 (Inter Nationes)\n- Wie Jugendliche ihr Handy nutzen verarbeitet (www.yahoo.com)\n- Söhne und Töchter schreiben über ihre Eltern (Miteinander 3)\n- Übung «was passt zusammen ? Lektion 7» Praxis Deutsch als Fremdsprache\n- Steffi, die Steetworkerin (verarbeitet)\n- Die Traumberufe, Internet www google\n- Statistik aus Tatsachen über Deutschland 2005\n- Informationen und Statistik aus Tatsachen über Deutschland 1998 und 2005\n- Duden Grammatik und Übungsgrammatik für Anfänger (Hueber)\n- Der ideale Lehrer (von Aachen bis Zwiskau, Inter Nationes 93)', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
